changeSet.sql:
drop view if exists sch_report_sepa.request_feedback cascade;
drop view if exists sch_report_opred.request_feedback cascade;
drop view if exists sch_report_nrw.request_feedback cascade;
drop view if exists sch_report_niea.request_feedback cascade;
drop view if exists sch_report_ea.request_feedback cascade;

create or replace view sch_report_sepa.request_feedback as SELECT rf.* FROM request_feedback rf JOIN request_resource ca ON rf.request_id = ca.request_id AND ca.resource_type = 'CA' LEFT JOIN request_resource acc ON rf.request_id = acc.request_id AND acc.resource_type = 'ACCOUNT' WHERE ca.resource_id = 'SCOTLAND';
create or replace view sch_report_opred.request_feedback as SELECT rf.* FROM request_feedback rf JOIN request_resource ca ON rf.request_id = ca.request_id AND ca.resource_type = 'CA' LEFT JOIN request_resource acc ON rf.request_id = acc.request_id AND acc.resource_type = 'ACCOUNT' WHERE ca.resource_id = 'OPRED';
create or replace view sch_report_nrw.request_feedback as SELECT rf.* FROM request_feedback rf JOIN request_resource ca ON rf.request_id = ca.request_id AND ca.resource_type = 'CA' LEFT JOIN request_resource acc ON rf.request_id = acc.request_id AND acc.resource_type = 'ACCOUNT' WHERE ca.resource_id = 'WALES';
create or replace view sch_report_niea.request_feedback as SELECT rf.* FROM request_feedback rf JOIN request_resource ca ON rf.request_id = ca.request_id AND ca.resource_type = 'CA' LEFT JOIN request_resource acc ON rf.request_id = acc.request_id AND acc.resource_type = 'ACCOUNT' WHERE ca.resource_id = 'NORTHERN_IRELAND';
create or replace view sch_report_ea.request_feedback as SELECT rf.* FROM request_feedback rf JOIN request_resource ca ON rf.request_id = ca.request_id AND ca.resource_type = 'CA' LEFT JOIN request_resource acc ON rf.request_id = acc.request_id AND acc.resource_type = 'ACCOUNT' WHERE ca.resource_id = 'ENGLAND';
